/// Look up part metadata by name (e.g. `"MainDocumentPart"`).
pub fn part_by_name(name: &str) -> Option<&'static PartInfo> {
    PARTS.iter().find(|p| p.name == name)
}

/// Look up part metadata by relationship type URI.
pub fn part_by_relationship_type(relationship_type: &str) -> Option<&'static PartInfo> {
    PARTS.iter().find(|p| p.relationship_type == relationship_type)
}

/// Returns true if `child_part_name` is an allowed child of `parent_part_name`.
pub fn is_allowed_child(parent_part_name: &str, child_part_name: &str) -> bool {
    part_by_name(parent_part_name)
        .map(|p| p.children.iter().any(|c| c.name == child_part_name))
        .unwrap_or(false)
}

/// Returns true if the parent allows multiple instances of the child part.
pub fn allows_multiple(parent_part_name: &str, child_part_name: &str) -> bool {
    part_by_name(parent_part_name)
        .and_then(|p| p.children.iter().find(|c| c.name == child_part_name))
        .map(|c| c.max_occurs_greater_than_one)
        .unwrap_or(false)
}
